def reachable(adj):
    """Warshall 传递闭包(Floyd 的布尔变体):把 min/+ 换成 OR/AND。
    输入布尔邻接矩阵 adj(adj[i][j]=是否有直接边),
    返回可达矩阵 r(r[i][j]=能否经 >=1 条边从 i 走到 j);不修改入参。"""
    n = len(adj)
    r = [list(map(bool, row)) for row in adj]
    for k in range(n):
        rk = r[k]
        for i in range(n):
            if not r[i][k]:                 # i 到不了 k,经 k 中转无意义
                continue
            ri = r[i]
            for j in range(n):
                if rk[j]:
                    ri[j] = True
    return r
